t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Blue Pearls from Stranglethorn"] = "Pérolas Azuis da Selva do Espinhaço",
		["On to Feathermoon"] = "Rumo a Plumaluna",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Cavalgue para o sul, saindo de {zone:1432} pelo desfiladeiro até {zone:1418}; {npc:2860} acampa na escavação.",
		["Take the boat to Theramore from the far pier."] = "Pegue o barco para a Ilha Theramore no píer mais distante.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "A próxima tarefa de Garra-de-acha fica para um guia posterior das {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Os Dragonetes Escaldantes fazem ninho na ravina a leste de {npc:2888}; deixe os Guardiões Flâmeos (elite) em paz. {item:4612} cai raramente: pegue se aparecer enquanto você farma.",
		["The battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers."] = "O esqueleto danificado fica na beira do acampamento dos troggs da Abóbada de Pedra; {quest:739}, o assassino de Agmundo, anda entre os Quebraossos.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "As duas primeiras jaulas ficam juntas na aldeia Cascasseca ao sul de {npc:5634}; a terceira está na aldeia seguinte, a leste. Qualquer troll Cascasseca pode soltar um colar.",
		["Theramore"] = "Ilha Theramore",
		["Warlock: {quest:3631}"] = "Bruxo: {quest:3631}",
		["Witherbark villages"] = "Aldeias Cascasseca",
		["{npc:1573}, the {object:32372}"] = "{npc:1573}, {object:32372}",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} fica nas docas onde o barco atraca.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "A próxima missão de {npc:2817} não dá experiência: pule.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "A próxima tarefa de {npc:2888} é uma caçada elite: pule.",
		["{npc:5634}'s cocktail needs parts from Kalimdor: skip it."] = "O coquetel de {npc:5634} precisa de ingredientes de Kalimdor: pule.",
		["{npc:5636}, beside the flight master at the top"] = "{npc:5636}, ao lado do mestre de voo, no alto",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884} continua pagando pelos colares: entregue os que sobrarem",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Giants and elementals"] = "Gigantes e elementais",
		["Gordunni ogres"] = "Ogros Gordunni",
		["Grimtotem camp"] = "Acampamento Temível Totem",
		["Grimtotem tauren"] = "Taurens Temível Totem",
		["Grind to 45"] = "Farme até o 45",
		["Hatecrest naga"] = "Nagas Cristafúria",
		["Hearth to Feathermoon."] = "Pedra de Regresso para o Domínio de Plumaluna.",
		["Rage Scar yetis"] = "Yetis Cortifúria",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "Volte para oeste pela estrada e depois para o norte até as colinas dos Yetis Cortifúria. Todo yeti daqui pode deixar cair um couro; um pode deixar cair um {quest:7735}, que {npc:7852} também paga.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Cavalgue para leste até o acampamento Gordunni nas colinas a sudeste do vale dos yetis: Bruxos Gordunni e Xamãs Gordunni ocupam o acampamento, Brutamontes Gordunni vagam pelas encostas ao redor e mais ao norte.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Cavalgue para o norte até o vale dos yetis. Todo Yeti Abominável pode deixar cair um couro grosso; {npc:5346} (nível 48) ronda o meio.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Cavalgue para nordeste até o posto avançado dos elfos noturnos na fronteira de {zone:1441}.",
		["Ride west to the friendly mountain giant at the foot of the hills. Land Walkers and Cliff Giants around him are elite: give them room."] = "Cavalgue para oeste até o gigante da montanha amistoso ao pé das colinas. Os Terrâmbulos e Gigantes do Penhasco ao redor dele são elite: mantenha distância.",
		["Ring the bell whenever {npc:7774} stops to wander, and lead her south to {npc:7765}."] = "Toque o sino sempre que {npc:7774} parar para vagar e leve-a para o sul até {npc:7765}.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Costívagos, Fundívagos e Ondarilhos (gigantes elite) andam pela costa ao norte da doca: atinja um com {item:18904} e mate o gigante encolhido. Elementais do Mar e Borrifos do Mar flutuam na mesma rebentação.",
		["The courier's boat"] = "O barco do mensageiro",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Caminhe para o sul pela ilha até as ruínas dos nagas; o mirante fica entre elas.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "para Tyrande Murmuréolo em {zone:1457}: a rota leva você lá no 47",
		["if you carry {quest:1100} from {zone:1441}"] = "se você trouxer {quest:1100} de {zone:1441}",
		["{item:11463}, from the backpacks"] = "{item:11463}, das mochilas",
		["{npc:14637}'s refills are level 55: skip them."] = "As recargas de {npc:14637} são de nível 55: pule-as.",
		["{npc:3936}, beside him"] = "{npc:3936}, ao lado dele",
		["{npc:7774} wanders the hills north of {npc:7765}, among the Northspring harpies; her bell is in the chest beside her."] = "{npc:7774} vaga pelas colinas ao norte de {npc:7765}, entre as harpias da Nascente Norte; o sino dela está no baú ao lado.",
		["{npc:7774}'s escort"] = "A escolta de {npc:7774}",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, no alto do bastião",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} fica para o fim do circuito no continente.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp."] = "Siga a costa para o sul até a enseada dos piratas. Os Piratas dos Mares do Sul lotam a praia e os barcos: avance pela borda e puxe um de cada vez. {npc:7883} fica do outro lado; a carga roubada de {npc:7881} está no acampamento.",
		["Gives the {item:8585}"] = "Dá o {item:8585}",
		["He runs off to keep Rizzle busy"] = "Ele sai correndo para distrair o Rebu",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Cavalgue para o leste pelas dunas até o porto goblin na costa nordeste.",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts."] = "Cavalgue para o noroeste até a colmeia Centiparte nas dunas. Qualquer Centiparte pode deixar cair partes de inseto.",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time."] = "Cavalgue para o sul até {quest:3362}. Os Coletores de Orvalho Moitagulhas deixam cair as glândulas; só algumas estão cheias, então guarde a Glândula de Orvalho Cheia. Moitagulhas Rotos e Fazraízes Moitaguhas dividem o vale. Os Moitagulhas Rotos são nível 48-50, acima de você: puxe um de cada vez.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Cavalgue para o sudoeste até o complexo dos ogros. Brutamontes Dunamalho e Impositores Dunamalho (46-48) o enchem; {npc:12046} (49) fica no meio, cercado de guardas: elimine-os primeiro.",
		["Rizzle's plans"] = "Projetos do Rebu",
		["The Wanted poster beside him"] = "O cartaz de Procurado ao lado dele",
		["Wastewander bandits"] = "Bandidos Errantes",
		["While {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "Enquanto {npc:4709} distrai o Rebu, os projetos dele ficam desprotegidos no acampamento gnomo do outro lado da pista.",
		["for {zone:1457}: the route takes you there at 47"] = "para {zone:1457}: a rota leva você lá no nível 47",
		["{npc:11758}, on the east side of town"] = "{npc:11758}, no lado leste da cidade",
		["{npc:5955}'s escort"] = "Escolta de {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, junto à torre d'água",
		["{npc:7408}, next to him"] = "{npc:7408}, ao lado dele",
		["{npc:7583}'s next ingredient grows in the {zone:1425}, and the route never brings it back: skip it."] = "O próximo ingrediente de {npc:7583} cresce em {zone:1425}, e a rota nunca o traz de volta: pule.",
		["{npc:7881}, in the port's tavern"] = "{npc:7881}, na taverna do porto",
		["{quest:2864}, north side of town"] = "{quest:2864}, no lado norte da cidade",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Ashmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52."] = "Javalis Jubacinza e Basiliscos Itarrubra dividem as encostas a sudoeste da fortaleza. Fique longe dos Javiltuscos mais ao sul: são nível 52.",
		["Boars and basilisks"] = "Javalis e basiliscos",
		["Hearthstone on cooldown? Ride back north-west."] = "Pedra de Regresso em recarga? Cavalgue de volta para o noroeste.",
		["Ride back north to Ironband's camp."] = "Cavalgue de volta para o norte até o acampamento de Bandaferro.",
		["Ride east along the south shore of the loch to Ironband's camp."] = "Cavalgue para o leste pela margem sul do lago até o acampamento de Bandaferro.",
		["Ride east through {zone:1430} into the {zone:1435} and south down the road into the {zone:1419}. The bloodmages' camp is the first stop beside the road."] = "Cavalgue para o leste por {zone:1430} até {zone:1435} e desça a estrada para o sul até {zone:1419}. O acampamento dos Magos Sangrentos é a primeira parada à beira da estrada.",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time."] = "Cavalgue para o oeste: Rasgarrindos Famintas vagam pelas colinas secas logo ao sul do acampamento dos Magos Sangrentos; Aguilhantes Escorpódes (nível 50) correm pelo meio do norte. Abutres {npc:5982} circulam sobre tudo. Puxe um de cada vez.",
		["Scorpoks and snickerfangs"] = "Escorpódes e rasgarrindos",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Atravesse o portal para {zone:1457}. O Templo da Lua fica no sul da cidade.",
		["Temple of the Moon"] = "Templo da Lua",
		["The bloodmages"] = "Os Magos Sangrentos",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "A segunda etapa dos Magos Sangrentos paga pelas mesmas partes com um item de bônus e sem experiência: pule.",
		["The druid trainers stand in the Enclave; {zone:1455} has none"] = "Os instrutores de druida ficam no Enclave; {zone:1455} não tem nenhum",
		["the book on her table"] = "o livro na mesa dela",
		["the soil comes from {zone:1449}, later"] = "o solo vem de {zone:1449}, depois",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, no alto da árvore",
		["{npc:7740}, beside her"] = "{npc:7740}, ao lado dela",
		["{npc:7744}: the last guide binds here, so this usually ticks at once"] = "{npc:7744}: o guia anterior vincula você aqui, então isto costuma ser marcado na hora",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "A próxima tarefa de {npc:7907} vai para {zone:1446}: pule.",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916}: guarde-a; as penas vêm no fim do guia de {zone:1428}",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, no alto da fortaleza",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["For {npc:8256} in {zone:1455}, later"] = "Para {npc:8256} em {zone:1455}, depois",
		["Golems and elementals"] = "Golems e elementais",
		["Greater Lava Spiders"] = "Aranhas de Lava Abrasadoras",
		["Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "Golems de Guerra Pesados patrulham o fundo de O Caldeirão, abaixo de Kalaran; Elementais de Magma vagam entre eles. Golems e elementais deixam cair o óleo; os elementais, os corações.",
		["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it."] = "Capatazes Ferro Negro e Feitores Ferro Negro tocam os escravos por todo O Caldeirão, e qualquer um deles pode carregar uma {item:10551}. Os Vaporistas Ferro Negro trabalham nas fornalhas no meio (a {item:18959}); os Atalaias Ferro Negro ficam nas cristas do sul (a Luneta do Espia). Qualquer {object:147516} pode deixar cair a {item:11818}: guarde-a.",
		["The Grimesilt outhouse"] = "A casinha de Pedrassuja",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "A próxima tarefa do prisioneiro, Livro-Caixa de {zone:1446}, manda você para {zone:1435} e {zone:1445}: pule.",
		["The spiders roam the plateaus and lava pools in the south-west of the gorge."] = "As aranhas vagam pelos platôs e poças de lava no sudoeste da garganta.",
		["The {object:179827} board"] = "O quadro {object:179827}",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}: o guia anterior leva você até aqui com a pedra de regresso, então isto costuma ser marcado na hora",
		["{object:147516} dwarves"] = "Anões {object:147516}",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Arquefilis fica ao lado do Rei Magni, em {object:171709}.",
		["Bind and train"] = "Vincule e treine",
		["Bones and equipment"] = "Ossos e equipamentos",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Atravesse o sul da cratera até {npc:9619}, junto à rampa.",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "Ossos de Dinossauro ficam no chão no sudoeste, entre os estegodons: eles são elite, pegue os ossos ao redor deles e consiga o resto com os Dimetrodontes. O {item:11112} da expedição fica na selva sudoeste.",
		["Eastern Pylon"] = "Torre de Cristal Leste",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Termina com {npc:9298}, em {zone:1452}: guarde",
		["Escort {npc:9999}"] = "Escolte {npc:9999}",
		["For {npc:7775} in {zone:1444}: keep it"] = "Para {npc:7775}, em {zone:1444}: guarde",
		["Four rune rubbings in {zone:1447}: keep it"] = "Quatro decalques de runas em {zone:1447}: guarde",
		["Grind to 50"] = "Suba até o nível 50",
		["Grind to 51"] = "Suba até o nível 51",
		["Lar'korwi Mates and the raft"] = "Lar'korwi Fêmeas e a jangada",
		["Northern Pylon"] = "Torre de Cristal Norte",
		["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "Desça a rampa para a cratera: {npc:9619} acampa ao pé dela.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Siga para o norte pelo lado leste até o planalto dos gorilas. {npc:9622}, um gorila de nível 55, fica na caverna mais funda: limpe os gorilas da entrada antes.",
		["Ride north along the western jungle back to the refuge."] = "Siga para o norte pela selva oeste de volta ao refúgio.",
		["Ride south along the eastern cliffs to {npc:9619} at the foot of the ramp."] = "Siga para o sul pelos penhascos leste até {npc:9619}, ao pé da rampa.",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales."] = "Desça para o sul pelo lado leste. Dimetrodontes Jovens pastam na selva leste e {npc:9165} voam perto dos penhascos leste; os dois deixam cair as escamas de {npc:9998}.",
		["Ride west back to the refuge."] = "Volte para o oeste até o refúgio.",
		["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; {npc:9166} nest on the southern cliffs if you still need kills."] = "Siga para o oeste a partir de {npc:9619}: a colmeia silitídea ocupa o sul da cratera. Use o Frasco para Amostra numa câmara de incubação, uma câmara com larvas penduradas. Vespas e Trabalhadoras Gorishi deixam cair {quest:3764}; {npc:9166} fazem ninho nos penhascos sul, se ainda precisar de abates.",
		["The Gorishi hive"] = "A colmeia Gorishi",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "As Lar'korwi Fêmeas rondam a selva a oeste de {npc:9619}. A jangada destruída fica na margem do lago ali; a mochila pequena está na água ao lado. Guarde a bússola, o mapa e a chave para {npc:8737}. Qualquer fera da cratera pode deixar cair {item:11116}: clique com o botão direito nele.",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "O Manguadonte morto fica junto à água, ao norte de {npc:9619}.",
		["The east side"] = "O lado leste",
		["The pelts come after loop 2, on the gorilla plateau"] = "As peles vêm depois do circuito 2, no planalto dos gorilas",
		["The pylon stands on the eastern cliffs."] = "A torre fica nos penhascos leste.",
		["The pylon stands on the slope east of the refuge. {npc:9166} circle the slopes around it: they count for {npc:9997} and drop {npc:9998}'s scales."] = "A torre fica na encosta a leste do refúgio. {npc:9166} sobrevoam as encostas ao redor: contam para {npc:9997} e deixam cair as escamas de {npc:9998}.",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "A torre fica nos penhascos oeste. {npc:9167} voam por todo o lado oeste.",
		["The relics are in the {zone:1428}: keep it"] = "As relíquias estão em {zone:1428}: guarde",
		["The wooden sign beside {npc:9997}"] = "A placa de madeira ao lado de {npc:9997}",
		["Western Pylon"] = "Torre de Cristal Oeste",
		["Xiggs waits in the {object:32359}."] = "Xisto espera em {object:32359}.",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}: para Ogtinc, em {zone:1447}, guarde",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}: o guia anterior leva você até aqui com a pedra de regresso, então isto costuma ser marcado na hora",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}, no fundo da caverna",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: os limos estão em {zone:1448}, guarde",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618} fica logo fora do refúgio.",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "O covil de {npc:9684} fica na selva ao norte de {npc:9619}, abaixo dos penhascos leste: use {item:11568} ali. {npc:9684} é nível 56: comece com a vida cheia.",
		["{npc:9997}'s friend {npc:9999} has gone missing."] = "{npc:9999}, amigo de {npc:9997}, desapareceu.",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, na entrada do refúgio",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}, na entrada do refúgio",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Druid training"] = "Treinamento de druida",
		["Mosshoof Coursers"] = "Ginetes Cascomusgo",
		["Optional: {npc:8395} wants two Undamaged Hippogryph Feathers from the hippogryphs around his camp. The data lists no experience for it."] = "Opcional: {npc:8395} quer duas Penas Intactas de Hipogrifo dos hipogrifos ao redor do acampamento dele. Os dados não indicam experiência para ela.",
		["Ride back east along the road to the Vigil."] = "Volte para o leste pela estrada até a Vigia de Morgan.",
		["Swim to the small island off the southern tip of {zone:1447}: {npc:8392} waits by the monument."] = "Nade até a pequena ilha na ponta sul de {zone:1447}: {npc:8392} espera junto ao monumento.",
		["Thaurissan Relics"] = "Relíquias Thaurissanas",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "Os ogros Pirobucho ocupam a grande rocha ao norte da Vigia de Morgan, com os Brutamontes no lado leste.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "Os fantasmas Altaneiros assombram as ruínas ao redor do santuário; os sátiros Haldarr ocupam o acampamento logo ao norte dele.",
		["The wildkin are in {zone:1452}: keep it"] = "Os coruscantes estão em {zone:1452}: guarde-a",
