		["The {item:18703}"] = "A {item:18703}",
		["from the {item:18703}"] = "da {item:18703}",
		["{item:18704}, from {npc:6109}"] = "{item:18704}, de {npc:6109}",
		["{item:18705}, from Onyxia"] = "{item:18705}, de Onyxia",
