		["Back to {npc:5675} in the {object:36082}. Place the hearts at the summoning circle below him and defeat the incubus they call."] = "Volte a {npc:5675} no {object:36082}. Coloque os corações no círculo de evocação abaixo dele e derrote o íncubo que eles chamarem.",
		["Back to {npc:5875} in the {object:172960}. Take the scarf to the summoning circle in {npc:3216}'s tent nearby and defeat the incubus it calls."] = "Volte a {npc:5875} na {object:172960}. Leve o lenço ao círculo de evocação na tenda de {npc:3216}, ali perto, e derrote o íncubo que ele chamar.",
		["Incubus (Horde)"] = "Íncubo (Horda)",
		["{npc:3363} keeps {object:173018}, east of the {object:172960} along the main street. He asks you to look for his mate, Krilge."] = "{npc:3363} cuida de {object:173018}, a leste da {object:172960}, na rua principal. Ele pede que você procure sua companheira, Krilge.",
		["{npc:5675}: he binds the incubus to you"] = "{npc:5675}: ele vincula o íncubo a você",
		["{npc:5875}: he binds the incubus to you"] = "{npc:5875}: ele vincula o íncubo a você",
		["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} in the Temple of the Damned, just north of him."] = "A versão de {object:1661}, para bruxos que pegaram a {quest:1472} de {npc:5675} em vez da de {npc:5875}. No nível 20, {npc:5675}, no {object:36082}, envia você a {npc:5693} no Templo dos Malditos, logo ao norte dele.",
} end)()
