t.guides["forever/horde/30-40/02-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "De volta ao norte, até o acampamento.",
		["Back to {object:3202}"] = "De volta a {object:3202}",
		["Back to {object:3202}."] = "De volta a {object:3202}.",
		["Basilisks and the Bloodscalp village"] = "Basiliscos e a aldeia Sanguescalpo",
		["Bloodscalp headhunters"] = "Caçadores de Cabeças Sanguescalpo",
		["Bloodscalp ruins"] = "Ruínas Sanguescalpo",
		["East of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}."] = "A leste dos ogros, Panteras Umbragorja (37-38) espreitam invisíveis até atacar; as Tigresas-do-espinhaço vagam pela mesma área e às vezes derrubam uma presa imaculada. Crocoliscos Arapuca ocupam o rio logo a oeste da selva; guarde as peles para {npc:2495}.",
		["Elder tigers and Lashtail raptors"] = "Tigres anciãos e Raptores Batecauda",
		["Fly to {object:3202}"] = "Voe até {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "Siga a estrada para o norte saindo de {object:3202}; o acampamento de caça de Rosarães Guima fica na colina a nordeste do rio. Daqui em diante, guarde toda página de {quest:338} que saquear: {npc:716} vai pedi-las depois.",
		["Follow the road south to {object:3202}."] = "Siga a estrada para o sul até {object:3202}.",
		["Green Hills pages"] = "Páginas de Grande Espinhaço: Veredas",
		["Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it."] = "Vá para oeste passando pelo acampamento. Raptores-do-espinhaço (33-34) caçam nas clareiras, e os trolls Sanguescalpo ocupam as ruínas no litoral: todo Sanguescalpo pode derrubar uma presa. Um {item:4614} é um saque muito raro deles: se cair um, leia-o.",
		["Hearth to {object:3202}"] = "Pedra de Regresso para {object:3202}",
		["Jungle Stalkers"] = "Espreitadores da Selva",
		["Lashtail raptors"] = "Raptores Batecauda",
		["Leave the {zone:1458} by the lift and walk up through the ruins to the zeppelin towers; the {object:3202} zeppelin is the one on the south-west tower."] = "Saia de {zone:1458} pelo elevador e suba pelas ruínas até as torres de zepelim; o zepelim de {object:3202} é o da torre sudoeste.",
		["Mistvale gorillas"] = "Gorilas do Vale da Névoa",
		["Mosh'Ogg camp"] = "Acampamento Mosh'Ogg",
		["Nesingwary's camp"] = "Acampamento de Rosarães Guima",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "As páginas de {item:2755} caem com cerca de 1% cada dos trolls Sanguescalpo e Rachacrânio; guarde toda página que saquear e procure o resto na casa de leilões. {npc:716} recebe os capítulos mais adiante neste guia.",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; take what drops and check the Auction House for the rest."] = "As páginas de {item:2755} caem com cerca de 1% cada dos trolls Sanguescalpo e Rachacrânio; pegue o que cair e procure o resto na casa de leilões.",
		["Raptors and the Bloodscalp trolls"] = "Raptores e os trolls Sanguescalpo",
		["Ride back south to {object:3202}."] = "Volte para o sul até {object:3202}.",
		["Ride north past Nesingwary's camp to the lake. The Venture Co. Geologists (34-36) work the camps along its western shore; they carry the Tumbled Crystals."] = "Siga para o norte passando pelo acampamento de Rosarães Guima até o lago. Os Geólogos da Empreendimentos S.A. (34-36) trabalham nos acampamentos ao longo da margem oeste; eles carregam os Cristais Rolados.",
		["Shadowmaw jungle and the Snapjaw river"] = "Selva das Panteras Umbragorja e rio dos Crocoliscos Arapuca",
		["Shadowmaw panthers"] = "Panteras Umbragorja",
		["Stranglethorn Tigers and Panthers (32-33) roam the hills east of the camp, along the lake shore."] = "Tigres-do-espinhaço e Panteras (32-33) vagam pelas colinas a leste do acampamento, ao longo da margem do lago.",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202} and train in the city before you fly on."] = "Pegue o zepelim de {zone:1454} na torre do lado oeste de {object:3202} e treine na cidade antes de seguir voando.",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads."] = "Os Caçadores de Cabeças Sanguescalpo (36-37) na aldeia do litoral carregam as cabeças encolhidas.",
		["The Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of {quest:338}."] = "Os trolls Sanguescalpo ocupam as ruínas subindo o litoral ao norte do recife e a aldeia mais adiante; todos podem derrubar um {item:3915}. Continue saqueando páginas de {quest:338}.",
		["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp; the Lashtail Raptors (35-36) hunt further south, towards {object:3202}."] = "Os Tigres-do-espinhaço Anciões (34-35) vagam pelas colinas a sudoeste do acampamento; os Raptores Batecauda (35-36) caçam mais ao sul, em direção a {object:3202}.",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "Os Espreitadores da Selva (40-41) caçam no litoral ao sul de {object:3202}. Eles estão bem acima de você: puxe um de cada vez e descanse entre as lutas.",
		["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "Os Raptores Batecauda (35-36) caçam na selva logo a nordeste de {object:3202}.",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}. Kill one Brute and one Witch Doctor (36-37); pull them one at a time."] = "Os ogros Mosh'Ogg acampam nas colinas logo a leste de {object:3202}. Mate um Brutamontes e um Mandingueiro (36-37); puxe um de cada vez.",
		["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "As Panteras Umbragorja (37-38) espreitam na selva a leste das colinas Mosh'Ogg e a nordeste, em direção ao lago; atacam da furtividade. Saqueie toda página de Grande Espinhaço: Veredas que encontrar pelo caminho.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "As Panteras Umbragorja vêm bem mais tarde, perto de {object:3202}",
		["The camp by the river"] = "O acampamento à beira do rio",
		["The zeppelin lands at the tower on the west side of the camp."] = "O zepelim pousa na torre do lado oeste do acampamento.",
		["Tigers and panthers"] = "Tigres e panteras",
		["Venture Co. camp"] = "Acampamento da Empreendimentos S.A.",
		["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear."] = "A oeste do acampamento, Basiliscos da Serra dos Cristais (34-35) ficam sobre as pedras; todo Sanguescalpo na aldeia mais adiante pode derrubar uma orelha.",
		["Young Stranglethorn Tigers prowl west of the camp, Young Panthers south and east of it."] = "Tigres-do-espinhaço Jovens rondam a oeste do acampamento, e Panteras Jovens ao sul e a leste dele.",
		["Young tigers and panthers"] = "Tigres jovens e panteras",
		["Zeppelin to {object:3202}"] = "Zepelim para {object:3202}",
		["Zeppelin towers"] = "Torres de zepelim",
		["{npc:2495}: the Snapjaw skins gathered earlier"] = "{npc:2495}: as peles de Crocolisco Arapuca coletadas antes",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}: para o Planalto Arathi, mais adiante na rota",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527} e seu {item:5177}",
		["{npc:729}, a level 37 tiger, prowls the hilltop south-west of the camp."] = "{npc:729}, um tigre de nível 37, ronda o topo da colina a sudoeste do acampamento.",
		["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "O acampamento dos caçadores desaparecidos de {npc:773} é o acampamento de Rosarães Guima: ande entre as tendas e a investigação é concluída. Crocoliscos do Rio ficam ao longo do rio, abaixo do acampamento.",
} end)()
t.guides["forever/horde/30-40/03-arathi-highlands"] = (function() return {
		["Boulderfist camp"] = "Acampamento Punho de Pedra",
		["Coyotes and buzzards"] = "Coiotes e urubus",
		["Daggerspine shore"] = "Praia Espinhadaga",
		["Escort the professor down to the shore. Two Daggerspine naga ambush him on the way: stay close."] = "Escolte o professor até a margem. Duas nagas Espinhadaga o emboscam no caminho: fique perto.",
		["Fleshstalker raptors"] = "Raptores Fareja-carne",
		["Fly to {object:3202}"] = "Voe para {object:3202}",
		["Follow the road north; {npc:4618}'s camp is on the way."] = "Siga a estrada para o norte; o acampamento de {npc:4618} fica no caminho.",
		["Greater Rock Elementals"] = "Elementais Maiores da Rocha",
		["Highland raptors"] = "Raptores do planalto",
		["Into the {zone:1418}"] = "Rumo a {zone:1418}",
		["Lesser Rock Elementals"] = "Elementais Inferiores da Rocha",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael."] = "A nordeste da Ruína do Martelo, os kobolds Bigodesseco mineram o desfiladeiro; os Kobolds da entrada e os Escavadores e Topógrafos mais ao fundo deixam cair as Partículas de Myzrael.",
		["Ride north; the outer circle stands in the middle of the highlands."] = "Cavalgue para o norte; o círculo externo fica no meio do planalto.",
		["Ride south-west to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "Cavalgue para sudoeste até a enseada dos goblins no litoral sul. {npc:2766} vigia do penhasco acima dela.",
		["Rock Elementals"] = "Elementais da Rocha",
		["Stonevault troggs"] = "Troggs da Abóbada de Pedra",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202}."] = "Pegue o zepelim para {zone:1454} na torre do lado oeste de {object:3202}.",
		["The Greater Rock Elementals (42-44, well above you) wander the gulches in the south-west; the bracers drop about one kill in five. Pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way."] = "Os Elementais Maiores da Rocha (42-44, bem acima de você) vagam pelas ravinas do sudoeste; as braçadeiras caem em cerca de uma morte a cada cinco. Puxe um de cada vez e descanse entre as lutas, ou deixe-os. Continue matando no caminho os coiotes e urubus que ainda faltam.",
		["The Syndicate hold the walled manor and its farm in the north-west; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets."] = "A Camarilha ocupa o solar murado e sua fazenda no noroeste; seus Bandoleiros, Mercenários e Tocaiantes levam os Amuletos de Pedra-sangrenta.",
		["The Witherbark trolls hold the village in the south-eastern hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village."] = "Os trolls Cascasseca ocupam a aldeia nas colinas do sudeste. Arremessadores guardam as cabanas externas; os Mandingueiros e Caçadores de Cabeças ocupam o coração da aldeia.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "O círculo interno fica ao sul do círculo oeste, a leste de Stromgarde.",
		["The next guide heads into {zone:1445}."] = "O próximo guia segue para {zone:1445}.",
		["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate."] = "A fortaleza orc no extremo leste da estrada. {npc:2851}, a mestre dos mantícoras, fica junto ao portão.",
		["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "Os elementais pequenos vagam pelas planícies logo a oeste do acampamento de {npc:2921}. Todo elemental da rocha da zona pode deixar cair Estilhaços de Elemental da Rocha para {npc:6868}: guarde-os.",
		["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "A próxima tarefa da pedra exige Fozruk, um elite de nível 42: deixe-a.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2689}"] = "{object:2689}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "Os {object:2701} ficam no fundo do desfiladeiro.",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Treine enquanto estiver em {zone:1458}: os instrutores ficam no {object:36070}, no {object:36073} e no {object:36082} (paladinos: {npc:260093}).",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "A oeste da enseada, os Saqueadores e Feiticeiras Espinhadaga (38-40) ocupam a praia: puxe um de cada vez. Os dois naufrágios ficam nas águas rasas em frente, com as cartas e os diários dentro; as gemas ficam no fundo do mar em volta dos naufrágios.",
		["Zeppelin to the {zone:1458}"] = "Zepelim para {zone:1458}",
		["Zeppelin to {zone:1454}"] = "Zepelim para {zone:1454}",
		["Zeppelin tower"] = "Torre do zepelim",
		["for {npc:5395} in {zone:1443}, in the next guide"] = "para {npc:5395}, em {zone:1443}, no próximo guia",
		["{item:3713}, for \"Swamp Eye\" Jarl in {zone:1445}"] = "{item:3713}, para Zé \"Olho de Lama\", em {zone:1445}",
		["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "A próxima {quest:678} de {npc:2771} é contra elites Punho de Pedra: deixe-a.",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920}: só se você tiver {item:2868} ({skill:164} ou a Casa de Leilões)",
		["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "{object:1661} não tem instrutor de caçador nem de xamã: pegue o zepelim de {zone:1454} na mesma torre, treine na cidade e depois pegue o zepelim de {zone:1458} na torre do lado de fora do portão principal de {zone:1454}.",
		["{zone:1458} trainers"] = "Instrutores de {zone:1458}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Darkfang spiders"] = "Aranhas Presanegra",
		["For {npc:2519} at {object:3202}, in the next guide"] = "Para {npc:2519} em {object:3202}, no próximo guia",
		["Hearth to Shadowprey"] = "Regressar para a Aldeia Pescassombra",
		["Kodo bones and ghosts"] = "Ossos de kodo e fantasmas",
		["Maraudine totems"] = "Totens Maraudinos",
		["Mirefin murlocs"] = "Murlocs Lamapina",
		["Pick up the kodo bones scattered across the graveyard, and use the {item:15848} among the bones: the ghosts it draws drop the ghost-o-plasm."] = "Pegue os Ossos de Kodo espalhados pelo cemitério e use o {item:15848} entre os ossos: os fantasmas que ele atrai deixam cair o fantasmoplasma.",
		["Ride back west to Brackenwall with the head."] = "Cavalgue de volta para oeste até Muralha Verde com a cabeça.",
		["Ride north up the road to the hut by the road north of the graveyard."] = "Cavalgue para o norte pela estrada até a cabana junto à estrada ao norte do cemitério.",
		["Ride on south-west to Shadowprey."] = "Siga cavalgando para sudoeste até a Aldeia Pescassombra.",
		["Ride west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely."] = "Cavalgue para oeste atravessando o pântano. Os Cospeçonhas Presanegra nas cristas ao norte de Muralha Verde deixam cair as glândulas de veneno. Infiltradores de Theramore (35-36) se esgueiram pela mesma mata: estão furtivos, então olhe com atenção.",
		["Slitherblade coast"] = "Costa dos Sibilâmina",
		["Stinky Ignatz"] = "Inácio \"Cascão\"",
		["Swamp Eye Jarl"] = "Zé \"Olho de Lama\"",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "Pegue a estrada para o norte na bifurcação até a aldeia ogra de Muralha Verde.",
		["The Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes."] = "As aranhas Névoa Negra lotam a entrada da caverna a noroeste de Muralha Verde; todo tipo deixa cair olhos.",
		["The next guide takes you back to {zone:1434}."] = "O próximo guia leva você de volta à {zone:1434}.",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "só se você tiver uma {item:3853} ({skill:164} ou a Casa de Leilões)",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, na borda sul da aldeia, onde chega a estrada",
		["{npc:5395} and {npc:5412} stand in the post just west of {npc:11596}'s camp."] = "{npc:5395} e {npc:5412} ficam no posto logo a oeste do acampamento de {npc:11596}.",
		["{npc:6791}: the last guide binds here, so this usually ticks at once"] = "{npc:6791}: o guia anterior vincula você aqui, então isto costuma ser marcado na hora",
		["{object:20985}, beside the manor"] = "{object:20985}, ao lado do solar",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, agora que {npc:4791} leu o relatório",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Draenethyst crystals"] = "Cristais de draenetista",
		["Fly to {object:3202}"] = "Voe para {object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "Siga a costa para o sul. As nagas exploradoras andam pela água ao longo da costa e levam os feixes de junco; {object:759} borbulha nas colinas logo a leste delas.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals."] = "Mais ao norte, os goblins da Empreendimentos S.A. cavam na mina a leste da estrada; mineradores, encarregados, topógrafos e engenhoqueiros deixam cair os cristais.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "Entregue as presas a Unbagwa e fique perto dele: ele chama três ondas de gorilas, depois {npc:1514}. Enfrente-os um de cada vez.",
		["Hearth to {object:3202}"] = "Regresse para {object:3202}",
		["Into the {zone:1435}"] = "Rumo a {zone:1435}",
		["Jungle stalkers"] = "Espreitadores da selva",
		["Mistvale gorillas"] = "Gorilas do Vale da Névoa",
		["Naga shore and the {object:759}"] = "Costa das nagas e {object:759}",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "A nordeste do Vale da Névoa, os seguidores de Zanzil acampam na selva; todos eles podem levar o preparado.",
		["Pirate ghosts"] = "Fantasmas piratas",
		["Ride north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "Cavalgue para o norte até as ruínas Rachacrânio, a leste da mina da Empreendimentos S.A.; puxe os caçadores de cabeças e os berserkers um de cada vez. {npc:1059} guarda as ruínas do sudoeste, e uma pilha de crânios-troféu fica no lado norte das ruínas. Todo Rachacrânio pode deixar cair uma presa ou um colar: os colares são a parte demorada, então continue matando no acampamento dos guerreiros ao norte das ruínas até ter todos.",
		["Ride north up the road to the hunters' camp."] = "Cavalgue para o norte pela estrada até o acampamento dos caçadores.",
		["Ride north up the road; the hunters camp on the hill above the river."] = "Cavalgue para o norte pela estrada; os caçadores acampam na colina acima do rio.",
		["Ride north-west to {object:3202}."] = "Cavalgue para noroeste até {object:3202}.",
		["Ride west to {object:3202}."] = "Cavalgue para o oeste até {object:3202}.",
		["Sawtooth crocolisks"] = "Crocoliscos Dentesserra",
		["Sawtooth snappers"] = "Tartaliscas Dentesserra",
		["Skullsplitter warriors"] = "Guerreiros Rachacrânio",
		["The Bloodsail ships"] = "Os navios da Vela Sangrenta",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "Os gorilas vagam pelo vale em volta de Unbagwa. Os anciões deixam cair os miúdos; qualquer um deles pode deixar cair uma presa.",
		["The last skulls are in the ruins a short ride west, on the way back to {object:3202}."] = "Os últimos crânios ficam nas ruínas um pouco a oeste, no caminho de volta para {object:3202}.",
		["The next guide starts here and takes you to {zone:1446}."] = "O próximo guia começa aqui e leva você até {zone:1446}.",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp."] = "Os próximos crânios-troféu ficam nas pequenas ruínas logo ao norte do acampamento dos guerreiros.",
		["The snappers line the strand south of the post."] = "As tartaliscas ocupam a praia ao sul do posto.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "Os raptores espreitadores caçam na selva ao sul de {object:3202}, rumo à costa oeste.",
		["Venture Co. mine"] = "Mina da Empreendimentos S.A.",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "A oeste da expedição, os chefes Sanguescalpo {npc:1061} e {npc:1062} ficam juntos nas Ruínas de Zul'Kanda. Elimine os guardas primeiro, depois puxe os dois.",
		["Zanzil's camps"] = "Acampamentos de Zanzil",
		["Zul'Kunda"] = "Ruínas de Zul'Kanda",
		["Zul'Mamwe"] = "Ruínas de Zul'Mamwe",
		["for Stoley in {zone:1446}"] = "para Esmirno, em {zone:1446}",
		["for a later stop in the {zone:1435}"] = "para uma parada posterior em {zone:1435}",
		["for later: the {zone:1425}, around level 48"] = "para depois: {zone:1425}, por volta do nível 48",
		["the {object:2076}"] = "o {object:2076}",
		["the {object:2076}, beside {npc:2497}"] = "o {object:2076}, ao lado de {npc:2497}",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Eastern Wastewander camps"] = "Acampamentos Errantes do leste",
		["Fly to {object:3202}"] = "Voe para {object:3202}",
		["Grimtotem camp"] = "Acampamento Temível Totem",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "Continue para o oeste até a costa. Os Olhabismos e Estalagarras da Areia nas praias deixam cair o sinalizador de socorro do OOX-22/FE em cerca de uma morte a cada quarenta: se cair, use-o para iniciar a missão.",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "Ao norte dos gnolls, os ogros ocupam um posto no alto de uma colina; puxe os Ogros-magos até você. O cobalto está nos montes de terra em volta do posto, e o pergaminho fica no chão lá dentro.",
		["Ride north-east to the goblin harbour on the coast."] = "Siga para o nordeste até o porto goblin na costa.",
		["Ride west into the middle of {zone:1444}. Kill a {npc:5308}, use {item:10699} on its body and kill the spirit that rises."] = "Siga para o oeste até o meio de {zone:1444}. Mate um {npc:5308}, use {item:10699} no corpo e mate o espírito que surgir.",
		["Riding at 40"] = "Montaria no 40",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel; no Skyborne riding trainer is known, so Skyborne try {npc:4752} too. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "Montaria exige nível 40 e custa 100 de ouro; aprender dá uma montaria. {npc:4752} ensina Orcs em {object:172958}, junto ao canil de {npc:3362}; não se conhece instrutor de montaria celonato, então os Celonatos também tentam {npc:4752}. As outras montarias da sua raça custam 20 de ouro cada: Colecionáveis, Montarias · Nível 40 tem um guia para cada.",
		["Rogue Vale screechers"] = "Guinchadores Errantes do Vale",
		["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often."] = "Ao sul pela costa, os piratas dos Mares do Sul ocupam a enseada. {npc:7883} e a carga roubada ficam no cais, no fundo dela. Qualquer pirata pode deixar cair um chapéu, os Sequestradores com mais frequência.",
		["Southern Gordunni ruins"] = "Ruínas Gordunni do sul",
		["Southern Wastewander camps"] = "Acampamentos Errantes do sul",
		["Sprite darters and Woodpaw alphas"] = "Dardejantes e Machos Alfa Patábua",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "Os taurens Temível Totem acampam ao lado do bosque dos Dardejantes; Saqueadores, Naturalistas e Xamãs carregam chifres.",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane."] = "Os gnolls Patábua acampam nas colinas logo a noroeste de Mojache; qualquer um deles pode deixar cair uma juba.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "A colmeia Zukk'ash se entoca nas colinas a sudeste do acampamento; {quest:7731} espera na câmara mais funda.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "O mapa de batalha fica no acampamento Patábua ao sul de Mojache.",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour."] = "Os Dardejantes voejam sobre o bosque logo a oeste de Mojache; quase todos deixam cair uma asa. Os Machos Alfa Patábua lideram os acampamentos a sudoeste dele: mate-os dentro de uma hora.",
		["The {object:3202} zeppelin leaves from the tower just north-east of {zone:1454}'s main gate."] = "O zepelim para {object:3202} sai da torre logo a nordeste do portão principal de {zone:1454}.",
		["The {zone:1454} zeppelin leaves from the tower beside {object:3202}; it lands just outside {zone:1454}'s main gate."] = "O zepelim para {zone:1454} sai da torre ao lado de {object:3202}; ele pousa logo fora do portão principal de {zone:1454}.",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Lobos: {npc:3362}, ao lado de {npc:4752}.",
		["Woodpaw battle map"] = "Mapa de batalha Patábua",
		["Woodpaw north camp"] = "Acampamento Patábua do norte",
		["Zeppelin to {object:3202}"] = "Zepelim para {object:3202}",
		["Zeppelin to {zone:1454}"] = "Zepelim para {zone:1454}",
		["Zeppelin tower"] = "Torre do zepelim",
		["for the {zone:1425}, around level 48"] = "para {zone:1425}, por volta do nível 48",
		["for {zone:1454}, around level 45"] = "para {zone:1454}, por volta do nível 45",
		["the {object:150075} in the square"] = "{object:150075} na praça",
		["water pouches in your bags"] = "bolsas de água nas bolsas",
		["{npc:3690}, riding trainer"] = "{npc:3690}, instrutor de montaria",
		["{npc:4752}, riding trainer"] = "{npc:4752}, instrutor de montaria",
		["{npc:4773}, riding trainer"] = "{npc:4773}, instrutora de montaria",
		["{npc:7953}, riding trainer"] = "{npc:7953}, instrutor de montaria",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}: para {zone:1454}, por volta do nível 45",
		["{npc:8579}: the screechers live in {zone:1444}"] = "{npc:8579}: os guinchadores vivem em {zone:1444}",
		["{quest:2863}: one hour from now"] = "{quest:2863}: daqui a uma hora",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Dragon caves"] = "Cavernas dos dragões",
		["Fly to {object:3202}"] = "Voe para {object:3202}",
		["Forest walkers"] = "Andarilhos da Floresta",
		["Frayfeather hippogryphs"] = "Hipogrifos Esfiapluma",
		["Monstrous Crawlers"] = "Rastejantes Monstruosos",
		["Murlocs of the Misty Reed"] = "Murlocs de Brumalga",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "A noroeste pela estrada, os Yetis Cortifúria vivem em volta das cavernas nas colinas. Qualquer um deles também pode deixar cair {quest:7738}, que inicia uma missão própria.",
		["Northspring harpies"] = "Harpias da Nascente Norte",
		["Onyxia's eggs"] = "Ovos de Onyxia",
		["Rage Scar yetis"] = "Yetis Cortifúria",
		["Ride back north to Brackenwall."] = "Volte para o norte até Muralha Verde.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Siga a estrada para o oeste; o pergaminho fica à beira da água, no extremo oeste do pântano.",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "Elementais do Mar e Borrifos do Mar percorrem a margem em volta do cais. Primeiro atinja os gigantes com {item:18904}: encolhidos, eles perdem a força de elite. Costívagos andam na água; os Terrâmbulos e Gigantes do Penhasco vagam pelas colinas mais ao norte.",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "Ao sul do vale, os Hipogrifos Esfiapluma pousam nas encostas; quase todos deixam cair tendões e fragmentos metálicos.",
		["Sprite darters and forest walkers"] = "Dardejantes e Andarilhos da Floresta",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "Os Murlocs do Pântano vivem na praia ao sul do posto; os Jogatintas ficam pela margem a leste dele e os Comecarnes mais a oeste, em volta das cabanas na margem oeste.",
		["The Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see on the way south."] = "Os Rastejantes Monstruosos andam pelas praias da costa leste, poucos e espalhados: mate cada um que vir no caminho para o sul.",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "As Harpias da Nascente Norte fazem ninho nas serras do extremo noroeste. São 48-50, alguns níveis acima de você: os Arautos do Vento curam, então mate-os primeiro e puxe uma por vez.",
		["The same murlocs again, plus the Oracles, who stay near the huts on the western shore."] = "Os mesmos murlocs de novo, mais os Oráculos, que ficam perto das cabanas na margem oeste.",
		["The small Horde post on the southern shore."] = "O pequeno posto da Horda na margem sul.",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "Os Dardejantes voejam sobre o bosque logo a oeste do acampamento e carregam {item:9589}; os Andarilhos Errantes da Floresta, um pouco mais a oeste, carregam os Pedaços de Lenha.",
		["The zeppelin to {zone:1454} leaves from the tower beside {object:3202}; it lands just north-east of {zone:1454}'s main gate."] = "O zepelim para {zone:1454} sai da torre ao lado de {object:3202}; ele pousa logo a nordeste do portão principal de {zone:1454}.",
		["Zeppelin to {zone:1454}"] = "Zepelim para {zone:1454}",
		["Zeppelin tower"] = "Torre do zepelim",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "para {npc:5598} em {zone:1425}, por volta do nível 48",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "para {object:2555} em {zone:1445}, mais adiante neste guia",
		["for the {zone:1425} owlbeasts, around level 48"] = "para os corujaursos de {zone:1425}, por volta do nível 48",
		["the {object:2555}"] = "{object:2555}",
		["{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "{npc:4500} é elite: é recomendado formar um grupo. Bata nele até ele se render e depois fale com {npc:4501}.",
		["{npc:7875}: for {npc:7010} in {zone:1454}, around level 50"] = "{npc:7875}: para {npc:7010} em {zone:1454}, por volta do nível 50",
		["{object:172958}, then the {object:172960} and the {object:172961}."] = "{object:172958}, depois {object:172960} e {object:172961}.",
		["{quest:7738}, a rare drop"] = "{quest:7738}, um saque raro",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Dark Iron Lookouts"] = "Atalaias Ferro Negro",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive."] = "Mais ao sul, o equipamento do Inspetor Júnior Anilhacido está na entrada de uma colmeia Centiparte.",
		["Greater Lava Spiders"] = "Aranhas de Lava Abrasadoras",
		["Heavy War Golems patrol the Cauldron below Kalaran and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it."] = "Golens de Guerra Pesados patrulham O Caldeirão abaixo de Kalaran e deixam cair o óleo; os Elementais de Magma e Fulgurantes que flutuam entre eles deixam cair os corações. Os Capatazes e Feitores Ferro Negro tocam os escravos pelas trilhas; um Feitor pode deixar cair a {item:11818}: guarde-a.",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "O próximo pedido dele requer o {item:10552} de sectários de elite: deixe-o.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Só com a {item:11818}: de volta a leste até a {object:173265} no sítio de escavação.",
		["Scrimshank's gear"] = "O equipamento de Anilhacido",
		["South down the road again."] = "Para o sul pela estrada de novo.",
		["South-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp."] = "A sudeste de Geringontzan, os bandidos Errantes acampam nas dunas; {npc:7847} fica no acampamento leste.",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "Os Atalaias Ferro Negro ficam nas cristas em volta das torres de vigia ao sul d'O Caldeirão; cerca de um em dez leva a {item:18960}.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Os Vaporistas Ferro Negro trabalham nas fornalhas no meio d'O Caldeirão; metade deles leva um {item:10551}, um em dez o {item:18959}. Escravos, Feitores e Capatazes também levam punhais.",
		["The Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge."] = "As Aranhas de Lava Abrasadoras vagam pelos platôs e poças de lava no sudoeste da garganta.",
		["The Steamsmiths' furnaces"] = "As fornalhas dos Vaporistas",
		["The {object:179827} board"] = "O quadro {object:179827}",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "A oeste de Geringontzan, use o {item:8584} junto ao poço d'água no acampamento troll.",
		["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in {zone:1446} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one."] = "A oeste do complexo, as criaturas-cacto enchem o vale; só os Coletores de Orvalho levam uma glândula de orvalho. A maioria das criaturas de {zone:1446} pode deixar cair o transmissor de emergência de OOX-17/TN, raramente: guarde-o se aparecer.",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts."] = "A oeste, os insetos Centiparte enxameiam em volta das colmeias; qualquer um deles deixa cair as peças.",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "a {item:8526} cresce em {zone:1425}, por volta do nível 48",
		["the {object:150075} in the square"] = "o {object:150075} na praça",
		["the {object:173265}"] = "a {object:173265}",
		["{item:11818}, a rare drop"] = "{item:11818}, item raro",
		["{item:8623}, a rare drop"] = "{item:8623}, item raro",
		["{npc:5955}'s escort"] = "Escolta de {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, ao lado do mestre de mantícoras",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["East of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south."] = "A leste da estrada, os javalis Jubacinza e os Grunhidos fuçam as encostas ao lado dos basiliscos Itarrubra. Fique longe dos Javiltuscos de nível 52 mais ao sul.",
		["East of the village, the violet flower grows in the hills."] = "A leste da aldeia, o Tragão Violeta cresce nas colinas.",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "Siga as estradas para leste pelas {zone:1425} até a aldeia troll na costa leste.",
		["Grind to 48"] = "Evolua até o 48",
		["Highvale"] = "Altovale",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "Seguindo a costa para o norte, a cesta de piquenique de {npc:14731} está na ilhota; um {npc:14748} a vigia.",
		["OOX-09/HL"] = "OOX-09/HL",
		["Only if you are not level 48 yet."] = "Só se você ainda não estiver no nível 48.",
		["Ride back north to the bloodmages."] = "Volte para o norte até os magos de sangue.",
		["Saltwater Snapjaws"] = "Mordeliscas de Água Salgada",
		["Silvermane Howlers"] = "Uivadores Jubaprata",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "Ao sul do pavilhão, os trolls Cascasseca ocupam suas aldeias. Cada um deles carrega um crânio: com vinte, use {item:15002} para fazer o Pique de Nimboya Repleto e finque-o dentro da aldeia.",
		["South-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "A sudoeste, os Uivadores Jubaprata vagam pelas colinas a leste das aldeias Cascasseca.",
		["The Vilebranch temples"] = "Os templos Ramatorpe",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "As tartarugas grandes rastejam pelas praias ao norte da aldeia. As garrafas de vinho do Porto de {npc:2491} também ficam nessas praias, mas a missão dele não está nesta rota. Uma mordelisca pode derrubar, raramente, o sinalizador de socorro do OOX-09/HL: guarde-o.",
		["The bloodmages"] = "Os magos de sangue",
		["The central hills"] = "As colinas centrais",
		["The eastern slopes"] = "As encostas do leste",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills."] = "As cinco missões pedem as mesmas partes: junte tudo de uma vez. A oeste da estrada, os abutres {npc:5982}, as Rasgarrindas Famintas, os Aguilhantes Escorpódes e os basiliscos Olho da Morte dividem as colinas.",
		["The northern beasts"] = "As feras do norte",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "As continuações pedem as mesmas partes de novo por um item de bônus e não dão experiência: ignore-as.",
		["Vilebranch soothsayers"] = "Adivinhos Ramatorpe",
		["Vulture hills"] = "Colinas dos abutres",
		["for {npc:6986} in {zone:1454}, around level 50"] = "para {npc:6986} em {zone:1454}, por volta do nível 50",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "para {npc:7825} na {zone:1458}, por volta do nível 50",
		["grind on {npc:5982} at the northern hills, {zone:1419}"] = "evolua com {npc:5982} nas colinas do norte, {zone:1419}",
		["{item:8704}, a rare drop"] = "{item:8704}, item raro",
		["{npc:14731}'s lunch"] = "O almoço de {npc:14731}",
		["{npc:6741}: for {zone:1456}, around level 50"] = "{npc:6741}: para {zone:1456}, por volta do nível 50",
		["{npc:7801}'s camp"] = "O acampamento de {npc:7801}",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}, {object:36126}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "Volte para o nordeste até {npc:8420}.",
		["Back to {object:3202}"] = "Volte para {object:3202}",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "Siga a estrada para o sul; os basiliscos tomam sol nas pedras a leste dela, no meio da selva. Os fragmentos caem com frequência.",
		["Frayfeather Hippogryphs"] = "Hipogrifos Esfiapluma",
		["Highborne and Haldarr satyrs"] = "Altaneiros e Sátiros Haldarr",
		["Ironjaw Basilisks"] = "Basiliscos Ferroqueixo",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "Guarde as entregas para {npc:4046}, {npc:8659} e {npc:6522}: você passa por {zone:1456}, {zone:1454} e {zone:1458} mais tarde.",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Guarde {quest:3444}: o baú de {npc:7771} é aberto numa visita futura.",
		["Only once all three robots are home"] = "Só depois que os três robôs estiverem em casa",
		["Ride into {zone:1447}"] = "Siga para {zone:1447}",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "Siga para o sudoeste até as ruínas. As quatro tabuletas ficam entre as ruínas, guardadas por nagas Iralisca; qualquer Sirena ou Mirmidão pode carregar a runa de {npc:8420}.",
		["Sea elementals"] = "Elementais do mar",
		["Sprite Darters"] = "Dardejantes",
		["Take the zeppelin back to {zone:1454}."] = "Pegue o zepelim de volta para {zone:1454}.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "As Aparições Altaneiras assombram as ruínas logo ao norte do santuário; os Sátiros Haldarr acampam um pouco mais ao norte.",
		["The Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "Os Terrâmbulos e Gigantes do Penhasco vagam pelas colinas ao norte do cais. Use primeiro {item:18904} em cada um: encolhidos, deixam de ser elite. Todo gigante encolhido deixa resíduo; use também o Recipiente de Muisec no corpo.",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock."] = "Os Elementais do Mar e Borrifos do Mar vagam pela costa em volta do cais.",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "O acampamento dos elfos sangrentos fica logo ao sul de {npc:8420}. As quatro peças de equipamento dele estão nos caixotes em volta do acampamento.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "As dragoletas voam pelo bosque logo a oeste do acampamento. Use o recipiente em cada uma que matar.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Os hipogrifos fazem ninho nas colinas a sudoeste do acampamento. Mate um e use o Recipiente de Muisec no corpo.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "Os arvorosos vagam pelas estradas da floresta entre o acampamento e o meio de {zone:1444}; são poucos, então procure ao longo das trilhas.",
		["The {object:2076} beside {npc:2519}"] = "{object:2076} ao lado de {npc:2519}",
		["To {object:3202}"] = "Para {object:3202}",
		["Undamaged Hippogryph Feathers"] = "Penas Intactas de Hipogrifo",
		["Wandering Forest Walkers"] = "Andarilhos Errantes da Floresta",
		["Zapped giants"] = "Gigantes encolhidos",
		["Zeppelin to {zone:1454}"] = "Zepelim para {zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}, no Drag",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}: os ursos ficam em {zone:1448}",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825} fica no {object:36082}.",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "O piche de {npc:7876} e as amostras de Almofarrista vêm de {zone:1449}.",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, ao lado do mestre de voo",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}, na borda leste do acampamento: não dá experiência, só um teleporte para a Torre de Azshara",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761} é coletado no próximo guia; o pagamento de {npc:4046} volta para {npc:8587} depois.",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Black Broodlings"] = "Filhotes Negros",
		["Bloodpetal Flayers"] = "Esfoladoras Pétala Sangrenta",
		["Cross the south of the crater to the pylon on the western cliffs."] = "Atravesse o sul da cratera até o pilar nos penhascos a oeste.",
		["Darrowshire Spirits"] = "Espíritos da Vila das Flechas",
		["Eastern Pylon"] = "Pilar do Leste",
		["Escort {npc:9999}"] = "Escolte {npc:9999}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Siga os penhascos para o sul até {quest:3821}, a colina dos ogros Pirobucho. Os restos de {npc:9136} estão no sopé.",
		["Free Darrowshire Spirits: talk to them"] = "Liberte os Espíritos da Vila das Flechas: fale com eles",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "Daqui em diante, pegue todo Cristal de Poder (azul, verde, vermelho, amarelo) e todo monte de {quest:3761} pelo caminho: 25 de solo ao todo, 20 para Hamuul e 5 para Almofarrista.",
		["Gorillas"] = "Gorilas",
		["Into the {zone:1427}"] = "Para {zone:1427}",
		["Into {zone:1449}"] = "Para {zone:1449}",
		["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "Guarde a isca: {npc:9684} é nível 56, e a segunda volta passa pelo covil dele.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Guarde {quest:4147} de {npc:9118} e a carta de {npc:8737} para guias futuros.",
		["Lar'korwi Mates"] = "Fêmeas de Lar'korwi",
		["Lashers and Threshers"] = "Açoitadeiras e Látegas",
		["North of Torwa, a dead Threshadon lies by the water."] = "Ao norte de Torwa, um Manguadonte morto jaz à beira da água.",
		["Northern Pylon"] = "Pilar do Norte",
		["Out of the refuge"] = "Saindo do refúgio",
		["Pestlezugg's next quest needs the {npc:10041}, an elite boss. Skip it."] = "A próxima missão de Almofarrista pede {npc:10041}, um chefe elite. Pule.",
		["Power Crystals and soil"] = "Cristais de Poder e solo",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Desça pelo lado leste da cratera até o pilar nos penhascos a leste.",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "Siga para o norte pelo lado leste. Açoitadeiras e Látegas Pétala Sangrenta enchem a selva.",
		["Ride south-west along the western cliffs. {npc:9167} fly over the west side, and Bloodpetal Trappers grow in the same jungle."] = "Siga para o sudoeste pelos penhascos a oeste. {npc:9167} voam pelo lado oeste, e Laçadoras Pétala Sangrenta crescem na mesma selva.",
		["Ride west to the dig site. {npc:7039} golems (53) stomp around it and drop the shards often; the {quest:4296} stands in its middle among the Thaurissan dwarves. Copy it."] = "Siga para o oeste até a escavação. Golens {npc:7039} (53) andam por ali e deixam cair os fragmentos com frequência; {quest:4296} fica no meio, entre os anões de Thaurissan. Copie.",
		["South of the hot springs, Stegodons graze and Dinosaur Bones drop from them or lie on the ground; Diemetradons nearby carry the scales {npc:9998} wants. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon."] = "Ao sul das fontes termais, Estegodons pastam, e Ossos de Dinossauro caem deles ou ficam no chão; os Dimetrodontes ali perto têm as escamas que {npc:9998} quer. Ravassauros caçam em bando no sudoeste: as garras são para {npc:8659}, e de vez em quando um carrega Um Diário Destroçado (item raro: pegue a missão só se conseguir um). Evite Grufo, um Estegodon de nível 57.",
		["Stegodons and ravasaurs"] = "Estegodons e ravassauros",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "Pegue {object:176092} no caixote ao lado de Arcabuz para {quest:5096}, feita na volta. Equipe {quest:5401}: Pedras do Flagelo só caem enquanto você a usa.",
		["Termite mounds"] = "Cupinzeiros",
		["Thaurissan dig site"] = "Escavação de Thaurissan",
		["The Gorishi hive"] = "A colmeia Gorishi",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "As Fêmeas de Lar'korwi rondam a selva a noroeste de {npc:9619}.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "A cabeça da boneca e suas duas metades estão nas casas em volta de {npc:10926}; junte-as pelas bolsas.",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "O caixote da expedição está num acampamento abandonado na selva a leste.",
		["The expedition's lost equipment lies in the south-west jungle."] = "O equipamento perdido da expedição está na selva a sudoeste.",
		["The gorillas live on the north-east plateau. Stay out of the deepest cave: {npc:9622} lives there."] = "Os gorilas vivem no platô a nordeste. Fique fora da caverna mais funda: {npc:9622} mora lá.",
		["The next guide starts here, at the chapel's flight master."] = "O próximo guia começa aqui, no mestre de voo da capela.",
		["The pylon stands on the slope east of the refuge."] = "O pilar fica na encosta a leste do refúgio.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "A jangada está na margem do lago a sudeste; a pequena mochila fica na água ao lado dela.",
		["The silithid hive fills the south of the crater. Gorishi wasps and workers drop the scent gland; use the Scraping Vial on the egg mass inside the first chamber. The Hive Queen at the bottom is an elite boss: stay out of her chamber. {npc:9166} nest on the cliffs above the hive; their scales are for {npc:9998}."] = "A colmeia silitídea ocupa o sul da cratera. Vespas Gorishi e Gorishi Trabalhadoras deixam cair a glândula odorífera; use o Frasco para Amostra Vazio na massa de ovos dentro da primeira câmara. A Rainha da Colmeia Gorishi, no fundo, é um chefe elite: fique fora da câmara dela. {npc:9166} fazem ninho nos penhascos acima da colmeia; as escamas são para {npc:9998}.",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}."] = "Os poços de piche ficam logo ao sul do refúgio. Monstros, Tocaieiros e Rastejantes de Piche deixam cair {item:11834}.",
		["The wooden sign beside {npc:9997}"] = "A placa de madeira ao lado de {npc:9997}",
		["Use the Mangled Journal to start it"] = "Use Um Diário Destroçado para iniciá-la",
		["Western Pylon"] = "Pilar do Oeste",
		["Western jungle"] = "Selva a oeste",
		["{item:11116}, a rare drop"] = "{item:11116}, item raro",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302} manda você até {npc:9298} em {zone:1452}: guarde.",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, {object:36078}, ao lado do mestre de voo",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}, {object:36073}",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}, no Apothecarium: os frascos são enchidos em {zone:1447} depois",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}, no fundo da caverna",
		["{npc:9618}, just outside"] = "{npc:9618}, logo do lado de fora",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} acampa no canto sudeste da cratera.",
		["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "Agora {npc:9619} pede a pele de {npc:9622}, lá na caverna a nordeste: pule.",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "Depois {npc:9623} quer {item:10561}, um item de {skill:202}. Pule, a menos que tenha um.",
		["{npc:9623}, the robot on the plateau"] = "{npc:9623}, o robô no platô",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "O covil de {npc:9684} fica logo ao sul do pilar. Use a isca de {npc:9619} ali; {npc:9684} é nível 56 e bate forte, então comece com a vida cheia.",
		["{npc:9998}, at the entrance"] = "{npc:9998}, na entrada",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, na entrada do refúgio",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999} está sentado na serra, perdido e exausto.",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} anda pelas cavernas e túneis de mina de {quest:3821}; se ele não estiver lá, limpe os ogros em volta das entradas até ele voltar.",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "As torres de vigia de Arcabuz, o caldeirão de Vandis e o barril de {npc:11615} ficam para uma visita posterior: guarde-as.",
		["Diseased Grizzlies"] = "Ursos-cinzentos Doentes",
		["Diseased Wolves"] = "Lobos Doentes",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "A leste do Posto Peçonha, o vale de crateras onde vagam as Feras e os Horrores Entrópicos. Mate dois de cada, depois vá até cada uma das três crateras de água vil.",
		["Jadefire moonwell"] = "Poço lunar Flamejade",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "Guarde o galho: {npc:5770} está em {zone:1456}.",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "Guarde {quest:5158}: {npc:5901} está em {zone:1413}.",
		["Keep {quest:8465} for {zone:1452}."] = "Guarde {quest:8465} para {zone:1452}.",
		["Northern crater"] = "Cratera do norte",
		["Only with 5 Deadwood Headdress Feathers"] = "Só com 5 Penas do Cocar de Lenha Morta",
		["Radley and Durgen"] = "Eiras e Durgen",
		["Ride back south-east to the Sanctuary."] = "Cavalgue de volta para sudeste até o Santuário.",
		["Ride north up the road again."] = "Cavalgue de novo para o norte pela estrada.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Cavalgue para noroeste até Andorhal. {npc:10667} espera na estalagem em ruínas do lado oeste da cidade; os esqueletos lá dentro são 54-57, então fique pelas bordas.",
		["Ride the road south through {zone:1448} to the Sanctuary."] = "Siga a estrada para o sul através de {zone:1448} até o Santuário.",
		["Scarlet Crusade"] = "Cruzada Escarlate",
		["Scarlet forward camp"] = "Acampamento avançado Escarlate",
		["Southern crater"] = "Cratera do sul",
		["Take the kitten to the same moonwell and release it there; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "Leve o gatinho ao mesmo poço lunar e solte-o ali; quando ele virar um {npc:10042}, leve-o de volta a {npc:9996} e clique nele para entregá-lo.",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "Os Anais estão entre os Tomos Mofados na prefeitura de Andorhal; abra-os até achar o certo.",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "A aldeia dos furbolgs Lenha Morta, logo a oeste do túnel. {npc:9462} (56) fica entre eles. {npc:11557}, um furbolg amistoso, fica no extremo norte da aldeia.",
		["The Jadefire moonwell"] = "O poço lunar Flamejade",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "O diário fica na casa da fazenda, o armário fica lá dentro e a casinha fica atrás dela. Um {npc:10816} leva a chave da casinha; {npc:10836} sai quando você abre a casinha e leva a chave do armário.",
		["The druids' camp is just past the border."] = "O acampamento dos druidas fica logo depois da fronteira.",
		["To {zone:1448}"] = "Para {zone:1448}",
		["Western crater"] = "Cratera do oeste",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}: os corujursos ficam em {zone:1452}",
		["{npc:10840}, at the graveyard's south end"] = "{npc:10840}, no extremo sul do cemitério",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}, na borda sul do acampamento",
		["{npc:11557}: keep 30 {quest:6031} for him; he trades only at Neutral with the Timbermaw"] = "{npc:11557}: guarde 30 {quest:6031} para ele; ele só negocia a partir de Neutro com os Presamatos",
		["{npc:11558}, at the tunnel mouth"] = "{npc:11558}, na entrada do túnel",
		["{npc:11610}'s last task needs level 53. The Scarlet Knights and Magi (54-55) working the lumber camp just south-west of her are the closest camp."] = "A última tarefa de {npc:11610} exige nível 53. Os Cavaleiros e Magos Escarlates (54-55) que trabalham no acampamento madeireiro logo a sudoeste dela são o acampamento mais próximo.",
		["{npc:1855}'s hunts are in the {zone:1423}: keep them for later."] = "As caçadas de {npc:1855} ficam em {zone:1423}: guarde-as para depois.",
		["{npc:9529}, just west of the camp"] = "{npc:9529}, logo a oeste do acampamento",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}, no lado oeste do Santuário",
		["{npc:9996}'s kitten"] = "O gatinho da {npc:9996}",
